css:
.section_lost{position:relative;overflow-x:hidden;overflow-y:hidden}
.ab_lost{position:relative;display:flex;flex-direction:column;min-height:100vh;padding-top:clamp(110px,12vw,150px);padding-bottom:clamp(60px,8vw,110px)}
.ab_rec.is-alert{color:var(--_color---status--alert)}
.ab_rec_dot.is-alert{background-color:var(--_color---status--alert)}
.ab_lost_404{position:relative;z-index:3;display:flex;justify-content:center;align-items:center;grid-row-gap:clamp(6px,1.5vw,24px);grid-column-gap:clamp(6px,1.5vw,24px);margin-top:clamp(24px,4vw,48px);font-weight:900;font-size:clamp(120px,27vw,400px);line-height:0.8;letter-spacing:-0.04em;color:var(--_color---text--primary);user-select:none}
.ab_lost_digit{position:relative;display:block}
.ab_lost_zero{position:relative;display:grid;align-items:center;justify-items:center;flex-grow:0;flex-shrink:0;flex-basis:auto;width:0.72em;height:0.72em}
.ab_lost_ring{position:absolute;top:-9%;right:-9%;bottom:-9%;left:-9%;border-top-width:1.5px;border-top-style:dashed;border-top-color:rgba(255,106,61,0.45);border-right-width:1.5px;border-right-style:dashed;border-right-color:rgba(255,106,61,0.45);border-bottom-width:1.5px;border-bottom-style:dashed;border-bottom-color:rgba(255,106,61,0.45);border-left-width:1.5px;border-left-style:dashed;border-left-color:rgba(255,106,61,0.45);border-top-left-radius:50%;border-top-right-radius:50%;border-bottom-right-radius:50%;border-bottom-left-radius:50%;pointer-events:none}
.ab_planet.is-lost{position:relative;left:auto;top:auto;right:auto;width:100%;cursor:grab;touch-action:none}
.ab_lost_tag{position:absolute;left:50%;top:calc(100% + 14px);transform:translateX(-50%);font-size:11px;font-weight:400;letter-spacing:0.1em;line-height:1.2;text-transform:uppercase;white-space:nowrap;color:var(--_color---text--tertiary)}
.ab_astro{position:absolute;left:8%;top:clamp(170px,20vw,300px);z-index:6;width:clamp(78px,8vw,120px);cursor:grab;touch-action:none;user-select:none}
.ab_astro_art{position:relative;width:100%;aspect-ratio:120 / 150}
.ab_astro_bubble{position:absolute;left:78%;bottom:92%;padding-top:8px;padding-right:10px;padding-bottom:8px;padding-left:10px;background-color:var(--_color---text--primary);color:var(--_color---brand--on-signal);font-size:11px;line-height:1.35;width:max-content;max-width:190px;pointer-events:none}
.ab_astro_hint{position:absolute;left:8%;top:calc(clamp(170px,20vw,300px) + clamp(118px,11vw,170px));z-index:5;font-size:10.5px;letter-spacing:0.1em;text-transform:uppercase;color:var(--_color---text--tertiary);pointer-events:none}
.ab_lost_grid{position:relative;z-index:4;display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,0.9fr);align-items:start;grid-row-gap:clamp(28px,5vw,80px);grid-column-gap:clamp(28px,5vw,80px);margin-top:clamp(56px,7vw,96px)}
.ab_lost_copy{position:relative;min-width:0}
.ab_lost_text{max-width:46ch;margin-top:20px;font-size:clamp(17px,1.5vw,20px);color:var(--_color---text--secondary)}
.ab_lost_path{padding-top:2px;padding-right:6px;padding-bottom:2px;padding-left:6px;border-top-width:1px;border-top-style:solid;border-top-color:rgba(255,106,61,0.25);border-right-width:1px;border-right-style:solid;border-right-color:rgba(255,106,61,0.25);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:rgba(255,106,61,0.25);border-left-width:1px;border-left-style:solid;border-left-color:rgba(255,106,61,0.25);background-color:rgba(255,106,61,0.08);font-size:0.85em;color:var(--_color---brand--signal);overflow-wrap:anywhere}
.ab_routes{position:relative;display:block;margin-top:34px;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair);background-color:var(--_color---neutral--glass)}
.ab_routes_head{display:flex;justify-content:space-between;padding-top:10px;padding-right:16px;padding-bottom:10px;padding-left:16px;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);font-size:11px;letter-spacing:0.12em;text-transform:uppercase;color:var(--_color---text--tertiary)}
.ab_routes_keys{position:relative}
.ab_route{position:relative;display:grid;grid-template-columns:34px minmax(0,1fr) auto;align-items:center;grid-row-gap:14px;grid-column-gap:14px;padding-top:16px;padding-right:16px;padding-bottom:16px;padding-left:16px;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);overflow-x:hidden;overflow-y:hidden;color:var(--_color---text--primary);text-decoration:none}
.ab_route_key{position:relative;z-index:1;display:grid;align-items:center;justify-items:center;width:28px;height:28px;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair-strong);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair-strong);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair-strong);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair-strong);font-size:12px;color:var(--_color---text--tertiary)}
.ab_route.is-primary{position:relative}
.ab_route_text{position:relative;z-index:1;min-width:0}
.ab_route_title{display:block;font-weight:800;font-size:clamp(18px,1.6vw,22px);line-height:1.05;text-transform:uppercase}
.ab_route_sub{display:block;margin-top:3px;font-size:11px;letter-spacing:0.06em;color:var(--_color---text--tertiary)}
.ab_route_go{position:relative;z-index:1;font-size:16px}
.ab_lsig{position:relative;display:block;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair);background-color:var(--_color---neutral--glass)}
.ab_lsig_head{display:flex;justify-content:space-between;align-items:center;padding-top:10px;padding-right:16px;padding-bottom:10px;padding-left:16px;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);font-size:11px;letter-spacing:0.12em;text-transform:uppercase;color:var(--_color---text--tertiary)}
.ab_lsig_status{color:var(--_color---status--alert);font-weight:500}
.ab_radar{position:relative;width:min(86%,360px);max-height:360px;aspect-ratio:1;margin-top:18px;margin-right:auto;margin-bottom:18px;margin-left:auto;overflow-x:hidden;overflow-y:hidden;border-top-width:1px;border-top-style:solid;border-top-color:rgba(59,227,138,0.35);border-right-width:1px;border-right-style:solid;border-right-color:rgba(59,227,138,0.35);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:rgba(59,227,138,0.35);border-left-width:1px;border-left-style:solid;border-left-color:rgba(59,227,138,0.35);border-top-left-radius:50%;border-top-right-radius:50%;border-bottom-right-radius:50%;border-bottom-left-radius:50%;cursor:crosshair}
.ab_radar_sweep{position:absolute;top:0;right:0;bottom:0;left:0;border-top-left-radius:50%;border-top-right-radius:50%;border-bottom-right-radius:50%;border-bottom-left-radius:50%}
.ab_radar_you{position:absolute;left:50%;top:50%;width:8px;height:8px;margin-left:-4px;margin-top:-4px;background-color:var(--_color---text--primary)}
.ab_lsig_grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair)}
.ab_lsig_cell{min-width:0;padding-top:12px;padding-right:16px;padding-bottom:12px;padding-left:16px}
.ab_lsig_dt{font-size:10.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--_color---text--tertiary)}
.ab_lsig_dd{margin-top:4px;font-size:14px;color:var(--_color---text--primary);overflow-wrap:anywhere}
.ab_lsig_dd.is-warn{color:var(--_color---brand--signal)}
.ab_lsig_hint{padding-top:10px;padding-right:16px;padding-bottom:10px;padding-left:16px;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair);font-size:11px;letter-spacing:0.06em;text-transform:uppercase;color:var(--_color---text--tertiary)}
@media screen and (max-width: 991px) {
.ab_lost_grid{grid-template-columns:minmax(0,1fr)}
.ab_astro{left:auto;right:4%;top:clamp(120px,24vw,200px);width:70px}
.ab_astro_hint{display:none}
.ab_astro_bubble{left:auto;right:70%}
.ab_routes_keys{display:none}
}
@media screen and (max-width: 479px) {
.ab_lost_404{font-size:34vw}
.ab_route{grid-template-columns:28px minmax(0,1fr) auto;grid-row-gap:10px;grid-column-gap:10px;padding-top:14px;padding-right:12px;padding-bottom:14px;padding-left:12px}
.ab_lsig_dd{font-size:12.5px}
}
